/* LAS ESCENAS. Cada una es una mancha pálida —el color al 10 % o menos, que a
   más se convierte en la pegatina que Pablo mandó quitar— y encima uno o dos
   trazos del mismo color a fuerza entera. El contraste entre los dos es lo que
   hace que se lea como un dibujo coloreado y no como un fondo de color. */
const ESCENAS: Record<string, { fondo: string; tinta: string; trazos: string[] }> = {
  /* El agua: dos olas que se salen del círculo, como si el mar siguiera. */
  mar:      { fondo: "#d9e7f1", tinta: "#3d7fa6", trazos: [
    "M6 80c7-6 13-6 20 0s13 6 20 0 13-6 20 0 13 6 20 0",
    "M14 90c6-5 11-5 17 0s11 5 17 0 11-5 17 0 11 5 15 0"] },
  /* El aire: la línea del horizonte y una nube pequeña arriba. */
  cielo:    { fondo: "#dde9f2", tinta: "#5586ac", trazos: [
    "M10 82h80",
    "M12 24c5-6 13-6 18 0 6-3 12 1 12 7"] },
  /* La noche: tres estrellas de cuatro puntas, ninguna centrada. */
  noche:    { fondo: "#dcdeee", tinta: "#3f4a8c", trazos: [
    "M16 22l2 5 5 2-5 2-2 5-2-5-5-2 5-2z",
    "M84 34l2 4 4 2-4 2-2 4-2-4-4-2 4-2z",
    "M24 78l1.5 4 4 1.5-4 1.5-1.5 4-1.5-4-4-1.5 4-1.5z"] },
  /* El suelo: la línea de tierra y dos matas de hierba. */
  campo:    { fondo: "#dde9d4", tinta: "#4c7a45", trazos: [
    "M8 84h84",
    "M20 84c0-6 2-10 5-12M74 84c0-5 2-9 5-11"] },
  /* El hielo: el horizonte partido por un pico. */
  hielo:    { fondo: "#dcebf3", tinta: "#5d95b2", trazos: [
    "M10 84h34M56 84h34",
    "M44 84l6-8 6 8"] },
  /* El calor: los rayos alrededor, cortos y largos alternando. */
  fuego:    { fondo: "#f8e2cd", tinta: "#c26b32", trazos: [
    "M50 6v10M50 84v10M6 50h10M84 50h10",
    "M19 19l7 7M74 74l7 7M81 19l-7 7M26 74l-7 7"] },
  /* El cuerpo: el latido del monitor cruzando por debajo. */
  cuerpo:   { fondo: "#f4dcda", tinta: "#b6544c", trazos: [
    "M6 82h20l5-11 7 22 6-14 5 3h39"] },
  /* La mesa: el canto y dos migas. */
  mesa:     { fondo: "#f3e4c9", tinta: "#a87f2e", trazos: [
    "M10 84h80",
    "M32 91.5h0.4M68 91.5h0.4"] },
  /* El taller: la cota de abajo, con sus dos topes. */
  taller:   { fondo: "#e0e4ea", tinta: "#5c6a79", trazos: [
    "M16 86h68",
    "M16 81v10M84 81v10"] },
  /* La historia: el renglón y el margen, como una página vieja. */
  historia: { fondo: "#ead8ba", tinta: "#96773f", trazos: [
    "M12 84h76",
    "M12 90h44"] },
  /* El motor: las rayas de velocidad, y en rojo, que es de lo que se habla. */
  motor:    { fondo: "#f7d9d5", tinta: "#c8322a", trazos: [
    "M8 74h30M46 74h20",
    "M14 84h26M50 84h14"] },
  /* El comodín, por si un dibujo se queda sin escena. */
  papel:    { fondo: "#ebe1cd", tinta: "#a98a55", trazos: ["M14 88h72"] },
};

/* `escena` es la excepción a mano: la escena vive en el dibujo, pero un mismo
   dibujo puede contar dos cosas distintas. El atardecer de Marte usa el mismo
   sol poniente que el nuestro y ahí el color naranja MIENTE, porque el dato es
   justamente que allí el atardecer es azul. Cuando pasa eso, el dato manda. */
export function Boceto({ nombre, escena }: { nombre: string; escena?: string }) {
  const b = BOCETOS[nombre];
  if (!b) return null;
  const esc = ESCENAS[escena ?? b.e] ?? ESCENAS.papel;
  return (
    <span className="boceto">
      {/* La escena: la mancha de color y sus trazos, detrás del dibujo. */}
      <svg className="boceto-escena" viewBox="0 0 100 100" aria-hidden focusable="false">
        <circle cx="50" cy="50" r="42" fill={esc.fondo} />
        <g fill="none" stroke={esc.tinta} strokeWidth="2.4" strokeLinecap="round">
          {esc.trazos.map((d, i) => <path key={i} d={d} />)}
        </g>
      </svg>
      {/* El dibujo, en la tinta de la página. */}
      <svg className="boceto-linea" viewBox={b.v} aria-hidden focusable="false"
           dangerouslySetInnerHTML={{ __html: b.d }} />
    </span>
  );
}
